from pwn import *

# Set up logging
context.log_level = 'debug'

def get_leaked_addr():
    # Run the program locally
    p = process('./ctf_files/prog')

    # Get initial output including leak
    output = p.recvuntil(b'>')
    p.close()

    # Extract leak from debug line
    for line in output.split(b'\n'):
        if b'[Debug] pool:' in line:
            leak_str = line.split(b'[Debug] pool:')[1].strip()
            return int(leak_str, 16)
    return None

# Collect multiple leaks
leaks = []
for i in range(5):
    addr = get_leaked_addr()
    if addr:
        leaks.append(addr)
        log.info(f"Leak {i}: {hex(addr)}")

