    # Check if leak is in common memory regions
    for leak in leaks:
        if 0x8048000 <= leak < 0x9000000:
            log.info(f"Leak {hex(leak)} is in text segment")
        elif 0x7f0000000000 <= leak < 0x7fffffffffff:
            log.info(f"Leak {hex(leak)} is in stack/libraries")
        elif 0x0 <= leak < 0x1000000:
            log.info(f"Leak {hex(leak)} is in null/low memory")
        else:
            log.info(f"Leak {hex(leak)} is in heap/mmap region")

