import gdb

def setup_breakpoints():
    # Set breakpoints on key memory operations
    gdb.execute('break *0x555555554000+0x1000') # RWX region start
    gdb.execute('break *0x555555554000+0xb000') # VM execution region

def dump_memory(addr, size):
    # Dump memory contents
    return gdb.execute(f'x/{size}bx {addr}', to_string=True)

def main():
    # Run the program
    gdb.execute('run')

    # Monitor memory operations
    while True:
        try:
            gdb.execute('continue')
        except gdb.error:
            break

        # Get current instruction
        pc = int(gdb.parse_and_eval('$pc'))
        inst = gdb.execute('x/i $pc', to_string=True)

        # Check memory operations
        if 'mov' in inst or 'lea' in inst:
            print(f'Memory operation at {hex(pc)}: {inst}')

        # Check RWX regions
        if (pc - 0x555555554000) >= 0x1000 and (pc - 0x555555554000) < 0xc000:
            print(f'Executing in RWX region at {hex(pc)}')
            print(dump_memory(pc, 16))

if __name__ == '__main__':
    main()

